// Resolve the PWA/Apple icon URLs for the `appearance.appIcon` setting.
//
// `appIcon` is stored as a base storage dir (no extension) holding the PNG
// variants generated by setting/upload_file:
//   images/settings/<domainId>/appIcon/<version>/192.png
//   images/settings/<domainId>/appIcon/<version>/512.png
//   images/settings/<domainId>/appIcon/<version>/maskable-512.png
//   images/settings/<domainId>/appIcon/<version>/apple-180.png
//
// The generic getSettingFileUrl() resolves image settings to `l.webp`, which
// browsers cannot use for the manifest/apple-touch-icon, so PWA icons need
// this dedicated PNG resolver.
import { runtimeEnv } from './runtimeEnv.js'

export const PWA_ICON_FILES = {
    icon192: '192.png',
    icon512: '512.png',
    maskable512: 'maskable-512.png',
    apple180: 'apple-180.png'
}

const RAW_EXT = /\.(png|webp|jpe?g|svg|ico)$/i

export function getPwaIconUrl(value, file = PWA_ICON_FILES.icon512) {
    if (!value) return ''
    const str = String(value).trim()
    if (!str) return ''
    if (/^https?:\/\//i.test(str) || str.startsWith('data:')) return str

    const baked = typeof VITE_FILES_BASE_URL !== 'undefined' ? VITE_FILES_BASE_URL : ''
    const base = (runtimeEnv('FILES_BASE_URL', baked) || 'https://files.shopik.co.il').replace(/\/+$/, '')
    const clean = str.replace(/^\/+/, '').replace(/\/+$/, '')

    // A raw file value (legacy/manual upload) is served as-is.
    if (RAW_EXT.test(clean)) return `${base}/${clean}`
    return `${base}/${clean}/${file}`
}
